using System.Windows;using System.Windows.Controls;using UnifiedMediaHub.Core;
namespace UnifiedMediaHub.App;
public partial class MainWindow
{
 bool bridgeInitializing=true,bridgeTokenVisible;int bridgeInstallIndex;
 static readonly string[] BridgeSteps=["第1步：在 Edge 的扩展商店中安装或打开 Tampermonkey。","第2步：用记事本打开项目源码 bridge 文件夹里的 umh-douyin-bridge.user.js（GitHub 仓库的 bridge 目录里也有）。","第3步：在 Tampermonkey 里新建脚本，删掉默认内容，粘贴该文件的全部内容并保存。","第4步：确认脚本已启用并刷新抖音页；不要额外开启 DOM 沙箱设置。","第5步：在管理器打开总开关和 Edge 桥接开关。","第6步：在抖音主页点击桥接按钮，再点“配置配对”，填写端口和令牌。","第7步：读取当前列表，默认先用20条，再手动点击“发送”。","第8步：回到管理器检查清单，勾选作品后点击下载。"];
 void InitializeBridge(){BridgePort.Text=services.Settings.EdgeBridgePort.ToString();BridgeEnabledBox.IsChecked=services.Settings.EdgeBridgeEnabled;services.BridgeImporter=ImportBridgeOnUi;bridgeInitializing=false;RefreshBridgeUi();}
 void ShowBridgeHint(){Pages.SelectedIndex=0;BridgeHint.Visibility=Visibility.Visible;StatusLine.Text="抖音列表请在 Edge 里用桥接脚本发送。作者作品请在 Edge 打开对应作者主页；不会启动专用浏览器。";}
 void BridgeSettings_Click(object sender,RoutedEventArgs e){Pages.SelectedIndex=3;EdgeBridgeSettings.BringIntoView();}
 void BridgeEnabled_Changed(object sender,RoutedEventArgs e){if(!bridgeInitializing)ApplyBridge();}
 void BridgeApply_Click(object sender,RoutedEventArgs e)=>ApplyBridge();
 void ApplyBridge()=>Start(async()=>{if(!int.TryParse(BridgePort.Text,out var port))throw new InvalidOperationException("请输入有效端口。");await services.ConfigureBridgeAsync(BridgeEnabledBox.IsChecked==true,port);RefreshBridgeUi();});
 void BridgeCopy_Click(object sender,RoutedEventArgs e)=>Start(()=>{if(services.Pairing==null)throw new InvalidOperationException("请先开启总开关和桥接开关。");Clipboard.SetText(services.Pairing.Token);StatusLine.Text="已复制配对令牌，请只粘贴到桥接脚本。";return Task.CompletedTask;});
 void BridgeShow_Click(object sender,RoutedEventArgs e)=>Start(()=>{if(services.Pairing==null)throw new InvalidOperationException("请先开启总开关和桥接开关。");bridgeTokenVisible=!bridgeTokenVisible;RefreshBridgeUi();return Task.CompletedTask;});
 void BridgeRegenerate_Click(object sender,RoutedEventArgs e)=>Start(()=>{if(services.Pairing==null)throw new InvalidOperationException("请先开启总开关和桥接开关。");services.Pairing.Regenerate();bridgeTokenVisible=false;RefreshBridgeUi();StatusLine.Text="配对令牌已重新生成，旧令牌立即失效；请手动更新脚本配置。";return Task.CompletedTask;});
 void BridgeInstructions_Click(object sender,RoutedEventArgs e){bridgeInstallIndex=0;BridgeInstallStep.Text=BridgeSteps[0];BridgeNextStep.Visibility=Visibility.Visible;BridgeNextStep.IsEnabled=true;}
 void BridgeNext_Click(object sender,RoutedEventArgs e){if(bridgeInstallIndex+1<BridgeSteps.Length)BridgeInstallStep.Text=BridgeSteps[++bridgeInstallIndex];BridgeNextStep.IsEnabled=bridgeInstallIndex+1<BridgeSteps.Length;}
 void RefreshBridgeUi(){if(BridgeHint==null||bridgeInitializing)return;var dy=Choice(SourcePlatform)=="douyin";BridgeHint.Visibility=BridgeProfileOption.Visibility=dy?Visibility.Visible:Visibility.Collapsed;if(!dy&&Choice(OwnKind)=="profile")OwnKind.SelectedIndex=0;BridgeStatus.Text=services.Bridge?.Enabled==true?$"桥接已开启：localhost:{services.Bridge.Port}（仅本机）":services.Settings.EdgeBridgeEnabled?"桥接未监听；请开启总开关，或检查端口错误提示。":"桥接已关闭，不监听端口。";if(!services.Hub.Enabled||services.Bridge?.Enabled!=true)bridgeTokenVisible=false;BridgeToken.Text=services.Pairing==null?"开启总开关和桥接后生成令牌":bridgeTokenVisible?services.Pairing.Token:new string('●',43);BridgeShowButton.Content=bridgeTokenVisible?"隐藏":"显示";var job=currentJobId==null?null:services.Repository.GetJob(currentJobId);var info=job?.Source.Kind=="bridge"?job.Source.Bridge:null;BridgeReviewPanel.Visibility=info is {ConfirmationRequired:true,Confirmed:false}?Visibility.Visible:Visibility.Collapsed;if(info!=null)SourceLabel.Text=$"来自 Edge 桥接 · {info.ViewerName} · {UserText.Kind(info.ListKind)}{(info.FolderTitle is {} folderTitle?" · "+folderTitle:"")} · {info.ItemCount} 条";}
 Task<BridgeImportResult> ImportBridgeOnUi(BridgePayload payload,CancellationToken ct)=>Dispatcher.InvokeAsync(async()=>{
  ct.ThrowIfCancellationRequested();if(!services.Hub.Enabled)throw new BridgeRequestException("disabled");if(services.Hub.ActiveCount>0||services.Hub.PendingCount>0)throw new BridgeRequestException("busy");services.Previews.Enable();services.Previews.EnablePlatform("douyin");var source=BridgeImports.Source(payload,services.Account("douyin")?.AccountId);var job=services.Repository.CreateJob(source,services.Settings.DownloadRoot,NewCategory());currentJobId=job.Id;Rows.Clear();Pages.SelectedIndex=0;dirty=true;
  try{await services.Hub.ImportBridgeAsync(job.Id,payload.Value).WaitAsync(ct);ct.ThrowIfCancellationRequested();}catch(OperationCanceledException){await services.Hub.StopJobAsync(job.Id);throw;}
  Refresh();RefreshBridgeUi();var finished=services.Repository.GetJob(job.Id);if(finished?.Status is "failed" or "paused")throw new InvalidOperationException("桥接导入未完成。");return new BridgeImportResult(job.Id,services.Repository.ListItems(job.Id).Count);
 }).Task.Unwrap();
 void BridgeConfirm_Click(object sender,RoutedEventArgs e)=>Start(()=>{if(currentJobId==null)throw new InvalidOperationException("请先选择桥接清单。");services.Repository.ReviewBridgeAccount(currentJobId,services.Account("douyin")?.AccountId);services.Repository.ConfirmBridge(currentJobId);services.Repository.UpdateJob(currentJobId,"completed",UserText.Error("bridge_snapshot"),reasonCode:"bridge_snapshot");Refresh();RefreshBridgeUi();return Task.CompletedTask;});
 void LegacyDouyin_Click(object sender,RoutedEventArgs e)=>Start(async()=>{RequireEnabled();if(SourceClassifier.TryClassify(SourceUrl.Text,out var parsed,out _)&&parsed?.Platform=="douyin"&&parsed.Kind=="profile"){await NewScan(parsed,true);return;}var account=services.Account("douyin")??throw new InvalidOperationException("旧方式需要先在专用浏览器确认抖音账号。");var kind=Choice(OwnKind);await NewScan(new(){Platform="douyin",Kind=kind,AccountId=account.AccountId,Url="https://www.douyin.com/user/"+Uri.EscapeDataString(account.AccountId)},true);});
}
